import{_ as n,C as i,o as r,c as s,a6 as e,E as u}from"./chunks/framework.DycQjAfF.js";const h=JSON.parse('{"title":"SOP Write Off & Barang Rusak","description":"Prosedur penghapusbukuan aktiva tetap (write off) di BPI, dan apa yang dilakukan jika menemukan barang rusak atau tidak terpakai.","frontmatter":{"title":"SOP Write Off & Barang Rusak","description":"Prosedur penghapusbukuan aktiva tetap (write off) di BPI, dan apa yang dilakukan jika menemukan barang rusak atau tidak terpakai.","status":"ditinjau","dasar":"Prosedur Penghapusbukuan Aktiva Tetap (Write Off) No. QP-4.3.3 Rev. 0","nomor_dokumen":"QP-4.3.3","versi":0.3,"pemilik":"Warehouse","pengesah":"Management Representative (30 Maret 2016)","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"SOP","sumber":["qp-write-off","ik-gudang-teknik"],"kata_kunci":["SOP","write off","penghapusbukuan","aktiva tetap","aset","CAPEX","berita acara kesepakatan write off","surat pengajuan write off","proses write off","scrap","ex pakai","obsolete","accounting","chief logistic","CFO","CEO","format D2","penjualan scrap","dead stock","barang rusak","material reject"]},"headers":[],"relativePath":"sop/dead-stock.md","filePath":"sop/dead-stock.md"}'),d={name:"sop/dead-stock.md"};function l(o,a,k,g,p,m){const t=i("MermaidDiagram");return r(),s("div",null,[a[0]||(a[0]=e('<h1 id="sop-write-off-barang-rusak" tabindex="-1">SOP Write Off &amp; Barang Rusak <a class="header-anchor" href="#sop-write-off-barang-rusak" aria-label="Permalink to &quot;SOP Write Off &amp; Barang Rusak&quot;">​</a></h1><p class="lead">Di BPI, <strong>write off</strong> berarti penghapusbukuan: catatan aset dihapus dari pembukuan perusahaan karena barangnya tidak bisa dipakai lagi. Halaman ini meringkas Prosedur Penghapusbukuan Aktiva Tetap (Write Off) No. QP-4.3.3 Rev. 0.</p><h2 id="apa-yang-bisa-di-write-off" tabindex="-1">Apa yang bisa di-write off? <a class="header-anchor" href="#apa-yang-bisa-di-write-off" aria-label="Permalink to &quot;Apa yang bisa di-write off?&quot;">​</a></h2><p>Prosedur ini berlaku untuk <strong>aktiva tetap BPI yang diperoleh melalui CAPEX</strong>, yaitu:</p><ul><li>aktiva tetap yang tidak sesuai lagi untuk digunakan, atau</li><li>barang bekas pakai (<em>ex pakai</em>) yang tidak bisa berfungsi lagi, karena rusak dan tidak bisa diperbaiki, atau karena suku cadangnya sudah tidak tersedia (<em>obsolete</em>).</li></ul><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Istilah</th><th>Artinya</th></tr></thead><tbody><tr><td data-label="Istilah"><strong>Write off</strong></td><td data-label="Artinya">Penghapusbukuan, yaitu penghapusan catatan aktiva tetap dari pembukuan BPI.</td></tr><tr><td data-label="Istilah"><strong>Aktiva tetap</strong></td><td data-label="Artinya">Aset berwujud milik BPI yang dibeli atau dibangun untuk dipakai dalam operasional perusahaan.</td></tr><tr><td data-label="Istilah"><strong>CAPEX</strong></td><td data-label="Artinya"><em>Capital Expenditure</em> (pembelanjaan modal), yaitu anggaran untuk memperoleh, menambah kapasitas, mengefisienkan, atau memperpanjang umur aktiva tetap.</td></tr></tbody></table><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>Pengguna (Supervisor) / pemilik barang</strong></td><td data-label="Tanggung jawab">Mengumpulkan dan mengenali barang, mengajukan surat write off ke Manager Departemen, memverifikasi ulang data barang fisik, dan menjaga barang sampai prosesnya selesai.</td></tr><tr><td data-label="Peran"><strong>Manager Departemen</strong></td><td data-label="Tanggung jawab">Memeriksa surat pengajuan dan mengecek barangnya ke lapangan, lalu membuat surat write off ke Manager Warehouse.</td></tr><tr><td data-label="Peran"><strong>Dept. Warehouse</strong></td><td data-label="Tanggung jawab">Meminta verifikasi data aset ke Dept. Accounting, meneruskan hasilnya ke pengguna, membuat Berita Acara Kesepakatan Write Off, lalu mengelola barang setelah berita acara terbit.</td></tr><tr><td data-label="Peran"><strong>Dept. Accounting</strong></td><td data-label="Tanggung jawab">Memverifikasi data aset perusahaan, termasuk nilai buku, berdasarkan nama dan spesifikasi barang.</td></tr><tr><td data-label="Peran"><strong>COO / CHRA / Senior Manager IT &amp; System, bersama Chief Logistic</strong></td><td data-label="Tanggung jawab">Membuat Berita Acara Kesepakatan Write Off.</td></tr><tr><td data-label="Peran"><strong>CFO dan CEO</strong></td><td data-label="Tanggung jawab">Menyetujui berita acara, dengan rekomendasi dijual, dimusnahkan, atau tindakan lain.</td></tr></tbody></table><h2 id="alur-write-off" tabindex="-1">Alur write off <a class="header-anchor" href="#alur-write-off" aria-label="Permalink to &quot;Alur write off&quot;">​</a></h2>',9)),u(t,{code:"flowchart%20TD%0A%20%20accTitle%3A%20Alur%20write%20off%20aktiva%20tetap%0A%20%20accDescr%3A%20Barang%20dikumpulkan%20dan%20diberi%20label%20Proses%20Write%20Off%2C%20diajukan%20ke%20Manager%20Departemen%20lalu%20ke%20Manager%20Warehouse.%20Warehouse%20meminta%20verifikasi%20data%20aset%20ke%20Accounting.%20Jika%20tercatat%20sebagai%20aset%2C%20dibuat%20Berita%20Acara%20Kesepakatan%20Write%20Off%20yang%20disetujui%20CFO%20dan%20CEO%2C%20lalu%20dicatat%20di%20ERP%20dan%20dijual%20sebagai%20scrap.%20Jika%20tidak%20tercatat%2C%20barang%20diserahkan%20ke%20Sub%20Gudang%20Teknik%20dan%20diproses%20sebagai%20scrap%20atau%20ex%20pakai.%0A%20%20A(%5BBarang%20tidak%20bisa%20dipakai%20lagi%5D)%3A%3A%3Adivisi%20--%3E%20B%5BKumpulkan%20di%20satu%20area%2C%3Cbr%2F%3Eberi%20identitas%20dan%20label%3Cbr%2F%3EProses%20Write%20Off%5D%3A%3A%3Adivisi%0A%20%20B%20--%3E%20C%5BSurat%20pengajuan%20ke%3Cbr%2F%3EManager%20Departemen%5D%3A%3A%3Adokumen%0A%20%20C%20--%3E%20D%5BManager%20Departemen%20cek%20ke%20lapangan%2C%3Cbr%2F%3Elalu%20kirim%20surat%20ke%20Manager%20Warehouse%5D%3A%3A%3Adivisi%0A%20%20D%20--%3E%20E%5BWarehouse%20minta%20verifikasi%3Cbr%2F%3Edata%20aset%20ke%20Accounting%5D%3A%3A%3Astaff%0A%20%20E%20--%3E%20F%7BTercatat%20di%3Cbr%2F%3Edata%20aset%20BPI%3F%7D%3A%3A%3Acek%0A%20%20F%20--%20Ya%20--%3E%20G%5BBerita%20Acara%20Kesepakatan%3Cbr%2F%3EWrite%20Off%5D%3A%3A%3Adokumen%0A%20%20F%20--%20Tidak%20--%3E%20H%5BDiserahkan%20ke%20Sub%20Gudang%20Teknik%2C%3Cbr%2F%3Ediproses%20sebagai%20scrap%2Fex%20pakai%5D%3A%3A%3Astaff%0A%20%20G%20--%3E%20I%5BDisetujui%20CFO%20dan%20CEO%5D%3A%3A%3Adivisi%0A%20%20I%20--%3E%20J%5BFormat%20D2%20dan%3Cbr%2F%3Epencatatan%20di%20ERP%5D%3A%3A%3Asistem%0A%20%20J%20--%3E%20K(%5BProsedur%20Penjualan%20Scrap%5D)%3A%3A%3Aselesai%0A"}),a[1]||(a[1]=e('<h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Identifikasi barang.</strong><ul><li>Kumpulkan barang yang akan diajukan di satu lokasi atau area tertentu.</li><li>Beri identitas pada barang: nama, spesifikasi, jumlah, dan lokasi asal penggunaan atau pemilik barang.</li><li>Beri tanda bertuliskan <strong>&quot;Proses Write Off&quot;</strong>, dan jaga barangnya sampai proses selesai.</li></ul></li><li><strong>Ajukan surat write off.</strong><ul><li>Pengguna atau pemilik barang mengirim surat pengajuan ke Manager Departemen. Surat ini bernomor dan berisi nama dan spesifikasi barang, lokasi asal, jumlah atau panjang dan berat, foto barang, serta keterangan pengajuan.</li><li>Manager Departemen memeriksa surat dan mengecek barangnya di lokasi.</li><li>Manager Departemen membuat surat write off bernomor ke Manager Warehouse, dengan melampirkan surat pengajuan dari pengguna.</li></ul></li><li><strong>Verifikasi data aset.</strong><ul><li>Dept. Warehouse meminta Dept. Accounting memverifikasi data barang, termasuk nilai bukunya.</li><li>Hasilnya diberikan ke pengguna untuk dicocokkan ulang dengan barang fisik.</li><li>Kalau nama dan spesifikasi barang <strong>tercantum</strong> di data aset, barang masuk ke Berita Acara Kesepakatan Write Off dan dilokalisir di area tertentu.</li><li>Kalau <strong>tidak tercantum</strong>, barang bisa langsung diserahkan ke Sub Gudang Teknik (Dept. Warehouse) dan diproses sesuai prosedur barang scrap atau ex pakai.</li></ul></li><li><strong>Buat dan setujui berita acara.</strong><ul><li>COO, CHRA, atau Senior Manager IT &amp; System, bersama Chief Logistic, membuat Berita Acara Kesepakatan Write Off. Isinya: nama, spesifikasi, jumlah, satuan, atau berat barang, lokasi penggunaan, alasan pengajuan, dan perkiraan nilai barang.</li><li>CFO dan CEO menyetujuinya, dengan rekomendasi dijual, dimusnahkan, atau tindakan lain.</li><li>Manager Warehouse mendokumentasikan berita acara yang sudah disetujui, lalu membagikannya ke Manager Departemen, Manager Accounting, COO, Chief Logistic, CHRA, Senior Manager IT, CFO, dan CEO.</li></ul></li><li><strong>Kelola barang setelah disetujui.</strong><ul><li>Sub Gudang Teknik membuat <strong>format D2</strong> dan menyerahkannya ke petugas pengelola data scrap, supaya barang dicatat di ERP.</li><li>Selanjutnya barang dikelola sesuai Prosedur Penjualan Scrap.</li></ul></li></ol><h2 id="dokumen-dan-penomoran-surat" tabindex="-1">Dokumen dan penomoran surat <a class="header-anchor" href="#dokumen-dan-penomoran-surat" aria-label="Permalink to &quot;Dokumen dan penomoran surat&quot;">​</a></h2><p>Semua nomor surat diawali <code>WO - BPI</code> (Write Off, PT Bakrie Pipe Industries), diikuti inisial, nomor surat, bulan (angka Romawi), dan tahun.</p><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Dokumen</th><th>Dari → kepada</th><th>Format nomor</th><th>Contoh</th></tr></thead><tbody><tr><td data-label="Dokumen">Surat pengajuan write off</td><td data-label="Dari → kepada">Pengguna/pemilik → Manager Departemen</td><td data-label="Format nomor"><code>WO - BPI / [inisial sub departemen] - [no.] / [bulan] / [tahun]</code></td><td data-label="Contoh"><code>WO - BPI / MTN Utility - 002 / V / 2016</code></td></tr><tr><td data-label="Dokumen">Surat pengajuan write off</td><td data-label="Dari → kepada">Manager Departemen → Manager Warehouse</td><td data-label="Format nomor"><code>WO - BPI / [inisial departemen] - [no.] / [bulan] / [tahun]</code></td><td data-label="Contoh"><code>WO - BPI / MTN - 002 / V / 2016</code></td></tr><tr><td data-label="Dokumen">Berita Acara Kesepakatan Write Off</td><td data-label="Dari → kepada">Chief terkait dan Chief Logistic → CFO dan CEO</td><td data-label="Format nomor"><code>WO - BPI / [COO/CHRA/...] - CLOG - [no.] / [bulan] / [tahun]</code></td><td data-label="Contoh"><code>WO - BPI / COO - CLOG - 002 / V / 2016</code></td></tr></tbody></table><h2 id="kalau-kamu-menemukan-barang-rusak-atau-tidak-terpakai" tabindex="-1">Kalau kamu menemukan barang rusak atau tidak terpakai <a class="header-anchor" href="#kalau-kamu-menemukan-barang-rusak-atau-tidak-terpakai" aria-label="Permalink to &quot;Kalau kamu menemukan barang rusak atau tidak terpakai&quot;">​</a></h2><p>Keputusan write off, penjualan, atau pemusnahan <strong>bukan</strong> wewenang peserta magang. Yang bisa kamu lakukan:</p><ol><li>Kenali tanda-tandanya: barang rusak, melewati tanggal kedaluwarsa, untuk mesin yang sudah tidak dipakai, atau lama tidak ada permintaan.</li><li>Pisahkan barang dari stok layak pakai dan beri tanda yang jelas, misalnya &quot;Tidak untuk dikeluarkan&quot;.</li><li>Catat kode, nama, jumlah, kondisi, lokasi asal, dan perkiraan penyebabnya.</li><li>Laporkan ke pembimbing, lalu ikuti keputusan pihak yang berwenang.</li></ol><p>Material <strong>baru</strong> yang datang dari vendor tetapi tidak sesuai spesifikasi tidak masuk proses write off. Material itu diberi tanda <strong>Material Reject</strong> dan diklaim ke vendor. Lihat <a href="./penerimaan-barang#kalau-material-tidak-sesuai">SOP Penerimaan Barang</a>.</p><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Barang rusak bisa berbahaya</p><ul><li>Consumable yang bocor atau kedaluwarsa, seperti oli, grease, dan sealant, ditangani dengan sarung tangan dan tidak dibuang sembarangan. Ikuti aturan limbah perusahaan.</li><li>Barang tajam atau pecah dibungkus agar tidak melukai orang lain.</li></ul></div><h2 id="pencegahan" tabindex="-1">Pencegahan <a class="header-anchor" href="#pencegahan" aria-label="Permalink to &quot;Pencegahan&quot;">​</a></h2><ul><li>Jalankan FIFO dan FEFO dengan disiplin.</li><li>Cek posisi stok sebenarnya sebelum mengajukan pembelian.</li><li>Laporkan jika mesin yang dilayani sudah tidak dipakai atau sudah dimodifikasi, agar suku cadangnya dievaluasi.</li></ul><h2 id="acuan" tabindex="-1">Acuan <a class="header-anchor" href="#acuan" aria-label="Permalink to &quot;Acuan&quot;">​</a></h2><p>QAM-1 Quality Assurance Manual BPI, HSE-M-1 HSE Manual BPI, ISO 9001:2008, OHSAS 18001:2007, dan ISO 14001:2014.</p>',15))])}const c=n(d,[["render",l]]);export{h as __pageData,c as default};
